const clone = require("clone");
const Flow = require('./Flow').Flow;
const context = require('../nodes/context');
const util = require("util");
const redUtil = require("@node-red/util").util;
const events = require("@node-red/util").events;
const flowUtil = require("./util");
const credentials = require("../nodes/credentials");


/**
 * Create deep copy of object
 */
 function deepCopy(obj) {
    return JSON.parse(JSON.stringify(obj));
}



/**
 * Evaluate Input Value
 */
 function evaluateInputValue(value, type, node) {
    if (type === "bool") {
        return (value === "true") || (value === true);
    }
    if (type === "cred") {
        return value;
    }
    return redUtil.evaluateNodeProperty(value, type, node, null, null);
}


/**
 * This class represents a submodel - which is handled as a special type of Flow
 */
class Submodel extends Flow {

    constructor(parent, globalFlow, submodelDef, submodelInstance){
        var submodels = parent.flow.submodels;
        var globalSubmodels = parent.global.submodels;
        var node_map = {};
        var node ;
        var wires;
        var i;

        var submodelInternalFlowConfig = {
            id:submodelInstance.id,
            configs: {},
            nodes: {},
            submodels: {},
        }

        if(submodelDef.configs){
            for( i in submodelDef.configs){
                if (submodelDef.configs.hasOwnProperty(i)){
                    node = createNodeInSubmodel(submodelInstance.id,submodelDef.configs[i]);
                    node_map[node._alias] = node;
                    submodelInternalFlowConfig.configs[node.id]=node;
                }
            }
        }
        if(submodelDef.nodes){
            for (i in submodelDef.nodes){
                if(submodelDef.nodes.hasOwnProperty(i)){
                    node = createNodeInSubmodel(submodelInstance.id, submodelDef.nodes[i]);
                    node_map[node._alias] =node;
                    submodelInternalFlowConfig.nodes[node.id] =node;
                }
            }
        }

        submodelInternalFlowConfig.submodels = clone(submodelDef.submodels || {});


        remapSubmodelNodes(submodelInternalFlowConfig.configs, node_map)
        remapSubmodelNodes(submodelInternalFlowConfig.nodes, node_map)

        super(parent, globalFlow, submodelInternalFlowConfig)

        this.TYPE = 'submodel';
        this.submodelDef = submodelDef
        this.submodelInstance = submodelInstance
        this.node_map = node_map
        this.path = parent.path+"/"+(submodelInstance._alias || submodelInstance.id);

        let id = submodelInstance.id
        if(submodelInstance._alias){
            id = submodelInstance._alias
        }

        this.templateCredentials = credentials.get(submodelDef.id) || {}
        this.instanceCredentials = credentials.get(id) || {}

        var env = [];

        if(this.submodelDef.env){
            this.submodelDef.env.forEach(e =>{
                env[e.name] =e;
                if(e.type === 'cred'){
                    e.value = this.templateCredentials[e.name]
                }
            })
        }

        if(this.submodelInstance.env){
            this.submodelInstance.env.forEach(e=>{
                    var old = env[e.name];
                    var ui = old ? old.ui : null;
                    env[e.name] = e;
                    if(ui){
                        env[e.name].ui = ui;
                    }
                    if(e.type === "cred"){
                        if(!old ||this.instanceCredentials.hasOwnProperty(e.name)){
                            e.value = this.instanceCredentials[e.name]
                        }else if(old){
                            e.value = this.templateCredentials[e.name]
                        }
                    }
                })
        }

        this.env = env;
    }

    start(diff){
        var self = this;

        var Node =require("../nodes/Node");

        if(this.submodelDef.status){
            var submodelStatusConfig = {
                id:this.submodelInstance.id+":status",
                type:"submodel-status",
                z: this.submodelInstance.id,
                _flow:this.parent,
            }
            this.statusNode = new Node(submodelStatusConfig)
            this.statusNode.on("input", function(msg){
                if(msg.payload!==undefined){
                    if(typeof msg.payload === "string"){
                        self.node.status({text:msg.payload})
                        return;
                    }
                    else if(Object.prototype.toString.call(msg.payload)=== "[object Object]"){
                        if(msg.payload.hasOwnProperty('text') || msg.payload.hasOwnProperty("fill") || msg.payload.hasOwnProperty('shape') || Object.keys(msg.payload).length === 0){
                            self.node.status(msg.payload)
                            return;
                        }
                    }

                    var text = util.inspect(msg.payload);
                    if(text.length > 32) { text = text.substr(0,32) + "...";}
                    self.node.status({text:text})
                }else if(msg.status !== undefined){
                    if(msg.status.hasOwnProperty("text") && msg.status.text.indexOf("common") === 0){
                        msg.status.text = "node-red:"+msg.status.text;
                    }
                    self.nodes.status(msg.status)
                }
            })
        }
        
        var submodelInstanceConfig = {
            id:this.submodelInstance.id,
            type: this.submodelInstance.type,
            z: this.submodelInstance.z,
            name:this.submodelInstance.name,
            wires:[],
            _flow:this
        }

        if(this.submodelDef.in){
            submodelInstanceConfig.wires = this.submodelDef.in.map(function(n){
                return n.wires.map(function(w){
                    return self.node_map[w.id].id;
                })
            })
            submodelInstanceConfig._originalWires = clone(submodelInstanceConfig.wires);
        }

        this.node = new Node(submodelInstanceConfig);
        this.node.on("input", function (msg){this.send(msg);})

        this.node.on("closes", function(done){
            this.status({});
            self.stop().finally(done)
        })

        this.node.status = status => this.parent.handleStatus(this.node, status);
        this._context = context.get(this._alias || this.id, this.z);

        this.node._updateWires = this.node.updateWires;

        this.node.updateWires = function(newWires){
            if(self.submodelDef.out){
                var node, wires, i, j;
                submodelInstanceConfig.wires = clone(submodelInstanceConfig._originalWires);
                for( i=0; i<self.submodelDef.out.length; i++){
                    wires = self.submodelDef.out[i].wires;
                    for(j=0; j<wires.length; j++){
                        if(wires[j].id != self.submodelDef.id){
                            node = self.node_map[wires[j].id]
                            if(node._originalWires){
                                node.wires = clone(node._originalWires)
                            }
                        }
                    }
                }

                var modifiedNodes = {}
                var submodelInstanceModified = false;
                for (i=0;i<self.submodelDef.out.length;i++) {
                    wires = self.submodelDef.out[i].wires;
                    for (j=0;j<wires.length;j++) {
                        if (wires[j].id === self.submodelDef.id) {
                            submodelInstanceConfig.wires[wires[j].port] = submodelInstanceConfig.wires[wires[j].port].concat(newWires[i]);
                            submodelInstanceModified = true;
                        } else {
                            node = self.node_map[wires[j].id];
                            node.wires[wires[j].port] = node.wires[wires[j].port].concat(newWires[i]);
                            modifiedNodes[node.id] = node;
                        }
                    }
                }
                Object.keys(modifiedNodes).forEach(function(id) {
                    var node = modifiedNodes[id];
                    self.activeNodes[id].updateWires(node.wires);
                });

                if (submodelInstanceModified) {
                    self.node._updateWires(submodelInstanceConfig.wires);
                }
            }
        }
        
        if(this.submodelDef.out){
            for (var i=0;i<this.submodelDef.out.length;i++) {
                // i: the output index
                // This is what this Output is wired to
                var wires = this.submodelDef.out[i].wires;
                for (var j=0;j<wires.length;j++) {
                    if (wires[j].id === this.submodelDef.id) {
                        // A subflow input wired straight to a subflow output
                        submodelInstanceConfig.wires[wires[j].port] = submodelInstanceConfig.wires[wires[j].port].concat(this.submodelInstance.wires[i])
                        this.node._updateWires(submodelInstanceConfig.wires);
                    } else {
                        var node = self.node_map[wires[j].id];
                        if (!node._originalWires) {
                            node._originalWires = clone(node.wires);
                        }
                        node.wires[wires[j].port] = (node.wires[wires[j].port]||[]).concat(this.submodelInstance.wires[i]);
                    }
                }
            }
        }

        if (this.submodelDef.status) {
            var submodelStatusId = this.statusNode.id;
            wires = this.submodelDef.status.wires;
            for (var j=0;j<wires.length;j++) {
                if (wires[j].id === this.submodelDef.id) {
                    // A subflow input wired straight to a subflow output
                    submodelInstanceConfig.wires[wires[j].port].push(submodelStatusId);
                    this.node._updateWires(submodelInstanceConfig.wires);
                } else {
                    var node = self.node_map[wires[j].id];
                    if (!node._originalWires) {
                        node._originalWires = clone(node.wires);
                    }
                    node.wires[wires[j].port] = (node.wires[wires[j].port]||[]);
                    node.wires[wires[j].port].push(submodelStatusId);
                }
            }
        }

        super.start(diff)
    }


    stop(stopList, removedList){
        const nodes = Object.keys(this.activeNodes);
        return super.stop(stopList, removedList).then(res=>{
            nodes.forEach(id=>{
                events.emit("node-status", {
                    id:id
                })
            })
        })
    }

    getSetting(name){
        if (!/^\$parent\./.test(name)) {
            var env = this.env;
            if (env && env.hasOwnProperty(name)) {
                var val = env[name];
                // If this is an env type property we need to be careful not
                // to get into lookup loops.
                // 1. if the value to lookup is the same as this one, go straight to parent
                // 2. otherwise, check if it is a compound env var ("foo $(bar)")
                //    and if so, substitute any instances of `name` with $parent.name
                // See https://github.com/node-red/node-red/issues/2099
                if (val.type !== 'env' || val.value !== name) {
                    let value = val.value;
                    var type = val.type;
                    if (type === 'env') {
                        value = value.replace(new RegExp("\\${"+name+"}","g"),"${$parent."+name+"}");
                    }
                    try {
                        return evaluateInputValue(value, type, this.node);
                    }
                    catch (e) {
                        this.error(e);
                        return undefined;
                    }
                } else {
                    // This _is_ an env property pointing at itself - go to parent
                }
            }
        } else {
            // name starts $parent. ... so delegate to parent automatically
            name = name.substring(8);
        }
        var parent = this.parent;
        if (parent) {
            var val = parent.getSetting(name);
            return val;
        }
        return undefined;

    }

    getNode(id, cancelBubble) {
        if (this.statusNode && this.statusNode.id === id) {
            return this.statusNode;
        }
        return super.getNode(id,cancelBubble);
    }



    handleStatus(node,statusMessage,reportingNode,muteStatus) {
        let handled = super.handleStatus(node,statusMessage,reportingNode,muteStatus);
        if (!handled) {
            if (!this.statusNode || node === this.node) {
                // No status node on this subflow caught the status message.
                // AND there is no Subflow Status node - so the user isn't
                // wanting to manage status messages themselves
                // Pass up to the parent with this subflow's instance as the
                // reporting node
                handled = this.parent.handleStatus(node,statusMessage,this.node,true);
            }
        }
        return handled;

    }


    handleError(node,logMessage,msg,reportingNode) {
        let handled = super.handleError(node,logMessage,msg,reportingNode);
        if (!handled) {
            // No catch node on this subflow caught the error message.
            // Pass up to the parent with the subflow's instance as the
            // reporting node.
            handled = this.parent.handleError(node,logMessage,msg,this.node);
        }
        return handled;
    }

}


function createNodeInSubmodel(submodelInstanceId, def){
     let node = clone(def);
     let nid = redUtil.generateId();
     node._alias = node.id
     node.id = nid;
     node.z = submodelInstanceId;
     return node;
}

function remapSubmodelNodes(nodes, nodeMap){
     for (var id in nodes){
         if(nodes.hasOwnProperty(id)){
             var node = nodes[id]
             if (node.wires){
                 var outputs = node.wires;
                 for( var j=0; j < outputs.length; j++){
                     var wires = outputs[j];
                     for(var k=0; k < wires.length; k++){
                         if(nodeMap[outputs[j][k]]){
                            outputs[j][k] = nodeMap[outputs[j][k]].id
                         }else{
                            outputs[j][k]= null;
                         }
                     }
                 }
             }
             if ((node.type === 'complete' || node.type === 'catch' || node.type === 'status') && node.scope) {
                node.scope = node.scope.map(function(id) {
                    return nodeMap[id]?nodeMap[id].id:""
                })
            } else {
                for (var prop in node) {
                    if (node.hasOwnProperty(prop) && prop !== '_alias') {
                        if (nodeMap[node[prop]]) {
                            node[prop] = nodeMap[node[prop]].id;
                        }
                    }
                }
            }
         }
     }
}


class SubmodelModule extends Submodel 
{

    constructor (type, parent, globalFlow, submodelDef, submodelInstance){
        super(parent.globalFlow, submodelDef, submodelInstance);
        this.TYPE=`module:${type}`;
        this.submodelType = type;
    }

    log(msg){
        if(msg.id){
            msg.id = this.id
        }
        if(msg.type){
            msg.type = this.submodelType
        }
        super.log(msg)
    }

}
function createSubmodel(parent, globalFlow, submodelDef, submodelInstance){
    return new Submodel(parent, globalFlow, submodelDef, submodelInstance)
}

function createModuleInstance(type, parent, globalFlow, submodelDef, submodelInstance){
    return new SubmodelModule(type, parent, globalFlow, submodelDef, submodelInstance);
}


module.exports = {
    init:function (runtime){},
    create:createSubmodel,
    createModuleInstance:createModuleInstance
}